(() => {
  const Z=window.Zucco,{state,platform:P,ui:U,ROUTES:R,icon:I,avatar:A,btn:BT,badge:B,money:M}=Z;
  const revenueChart=()=>`<svg class="revenue-chart" viewBox="0 0 640 180" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Monthly tuition revenue rose from 112 million UZS in June to 186.4 million UZS in November"><g fill="#65776C" font-family="Inter" font-size="10"><text x="0" y="18">200M</text><text x="0" y="65">160M</text><text x="0" y="112">120M</text><text x="7" y="159">80M</text></g><g stroke="#E3EAE5" stroke-width="1"><path d="M42 14H632M42 61H632M42 108H632M42 155H632"/></g><path d="M42 117C85 117 110 95 160 102S230 128 278 105S360 62 396 66S465 52 514 45S585 26 632 20V166H42Z" fill="#E8F3ED"/><path d="M42 117C85 117 110 95 160 102S230 128 278 105S360 62 396 66S465 52 514 45S585 26 632 20" fill="none" stroke="#146B52" stroke-width="2.5"/><circle cx="632" cy="20" r="4" fill="#146B52" stroke="white" stroke-width="2"/></svg><div class="chart-months"><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span><span>Nov</span></div>`;
  Z.renderers[R.DASHBOARD]=()=>Z.heading('Your academy, at a glance','Welcome back, Asilbek. Here is what needs your attention today.',`<span class="overview-date">${I('calendar')}Monday, 2 November 2026</span>`+BT('Add student','ext-new-student','plus','primary'))+
    U.metrics([['Active students',P.students.filter(s=>s.status==='Active').length,'Across 2 branches','users'],['Active groups',P.groups.filter(g=>g.status==='Active').length,'2 groups currently recruiting','group'],["Today's income",M(state.cashIncome+state.cardIncome),'<span class="text-success">Cash + terminal / card</span> · UZS','wallet','success'],['Open leads',state.leads.filter(l=>l.stage<5).length,'5 leads at trial stage','leads']])+
    `<div class="split-panels">${U.panel('Tuition revenue',`<div class="chart-summary"><strong class="mono">186,400,000 <span class="caption">UZS</span></strong>${B('↑ 12.8%','success')}<span class="grow"></span><span class="chart-legend"><span><i class="chart-dot"></i>Received</span></span></div>${revenueChart()}`,BT('View report','go:'+R.REPORTS,'arrow','ghost small'))}
    ${U.panel('Needs attention',`<div class="attention-list"><div class="attention-item"><span class="attention-icon warning">${I('alert')}</span><div><h3>24 students have overdue tuition</h3><p>18,600,000 UZS in outstanding balances.</p>${U.link('Review balances →','go:'+R.FINANCE)}</div></div><div class="attention-item"><span class="attention-icon">${I('calendar')}</span><div><h3>6 trial lessons scheduled today</h3><p>A warm welcome makes a lasting difference.</p>${U.link('Open admissions →','go:'+R.LEADS)}</div></div><div class="attention-item"><span class="attention-icon">${I('cash')}</span><div><h3>Payroll is ready for review</h3><p>3 calculations are waiting for approval.</p>${U.link('Review payroll →','go:'+R.PAYROLL)}</div></div></div>`)}
    </div><div class="split-panels"><section class="panel overview-lessons"><div class="panel-heading"><h2>Today's upcoming classes</h2>${BT('Full schedule','go:'+R.SCHEDULE,'arrow','ghost small')}</div><table class="compact-table"><thead><tr><th style="width:17%">Time</th><th style="width:38%">Course / group</th><th style="width:28%">Teacher</th><th>Room</th></tr></thead><tbody>${[['12:00','Frontend Development','FE-02','Sardor Tursunov','Lab 01'],['14:00','IELTS Foundation','IF-10','Nodira Saidova','102'],['15:00','Mathematics','MT-12','Jasur Aliyev','103']].map(([time,course,group,teacher,room])=>`<tr><td class="mono text-primary bold">${time}</td><td><div class="table-primary">${course}</div><p class="table-secondary">${group}</p></td><td><span class="row">${A(teacher,'','small')}<span class="caption">${teacher.split(' ')[0]} ${teacher.split(' ')[1][0]}.</span></span></td><td>${B(room)}</td></tr>`).join('')}</tbody></table></section>${U.panel('Enrollment by subject',U.bars([['English language','122 learners',76],['Mathematics','45 learners',36],['Technology','28 learners',24]]),BT('Courses','go:'+R.COURSES,'arrow','ghost small'))}</div>`;
  Z.renderers[R.REPORTS]=()=>Z.heading('Reports & insights','See what is growing, what is working, and where to focus.',`<select class="select report-period" aria-label="Reporting period" data-report-period><option>November 2026</option><option>October 2026</option></select>`+BT('Export summary','ext-export-report','download'))+
    U.metrics([['Tuition received','186.4M','<span class="text-success">↑ 12.8%</span> vs. previous month','wallet','success'],['Collection rate','94.2%','18.6M UZS still outstanding','checkCircle'],['Average attendance','92.6%','<span class="text-success">↑ 3.1 points</span> this month','book'],['Trial conversion','32.4%','28 of 86 leads enrolled','convert']])+
    `<div class="split-panels">${U.panel('Revenue trend',`<div class="row between"><span class="caption">June–November 2026 · UZS</span>${B('Last 6 months')}</div>${revenueChart()}`)}${U.panel('Active enrollments',`<div class="report-summary"><svg class="report-ring" viewBox="0 0 150 150" role="img" aria-label="195 course enrollments: English 63 percent, Mathematics 23 percent, Technology 14 percent"><circle cx="75" cy="75" r="56" fill="none" stroke="#EDF2EE" stroke-width="17"/><g transform="rotate(-90 75 75)" fill="none" stroke-width="17"><circle cx="75" cy="75" r="56" stroke="#146B52" stroke-dasharray="221.67 351.86"/><circle cx="75" cy="75" r="56" stroke="#5A9F7B" stroke-dasharray="80.93 351.86" stroke-dashoffset="-221.67"/><circle cx="75" cy="75" r="56" stroke="#BBDCCB" stroke-dasharray="49.26 351.86" stroke-dashoffset="-302.6"/></g><text x="75" y="73" text-anchor="middle" fill="#243D32" font-family="Inter" font-size="25" font-weight="600">195</text><text x="75" y="93" text-anchor="middle" fill="#65776C" font-family="Inter" font-size="10">enrollments</text></svg><div class="report-breakdown"><div class="row"><span>English language</span><strong>63%</strong></div><div class="row"><span>Mathematics</span><strong>23%</strong></div><div class="row"><span>Technology</span><strong>14%</strong></div></div></div>`)}
    </div>${U.table([['Course',29],'Enrollments','Monthly tuition','Attendance','Collection rate'],P.courses.filter(c=>c.status==='Active').map((c,i)=>`<tr><td>${U.link(c.name,'ext-open-course:'+c.id)}</td><td class="mono">${c.students}</td><td class="mono">${M(c.price,true)}</td><td>${B([94,91,96,89,93][i]+'%','success')}</td><td class="mono">${[96,92,95,94,97][i]}%</td></tr>`).join(''),'','<span>November 2026 · Sample reporting data</span><span>All branches</span>')}`;
  Z.renderers[R.LOGIN]=()=>`<main class="login-page" id="main"><section class="login-story"><div class="brand"><span class="brand-mark">z</span><span class="brand-word">zucco</span></div><div><h1>A clearer way to run your academy.</h1><p>From the first conversation to the next milestone. Bring your students, team, and operations together.</p><div class="login-preview"><div class="row between"><h2>Today at your academy</h2>${B('Monday, 2 Nov','accent')}</div>${[['09:00','IELTS Foundation','Madina K. · Room 201'],['12:00','Frontend Development','Sardor T. · Lab 01'],['16:00','General English','Aziza R. · Room 202']].map(([time,title,note])=>`<div class="login-preview-row"><span class="mono">${time}</span><div class="grow"><strong>${title}</strong><p>${note}</p></div>${I('checkCircle')}</div>`).join('')}</div></div><div class="login-story-footer"><span>Built around the way you teach.</span><span>© Zucco 2026</span></div></section><section class="login-main"><form class="login-form" id="demo-login-form"><h2>Welcome back</h2><p>Sign in to your Zucco Academy workspace.</p><div class="login-fields"><label class="stack"><span class="field-label">Phone number</span><input class="input field-control" name="phone" type="tel" value="+998 90 123 45 67" autocomplete="off" required aria-label="Phone number"></label><label class="stack"><span class="field-label">Password</span><span class="password-wrap"><input class="input field-control" name="password" id="demo-password" type="password" value="demo-workspace" autocomplete="off" required><button type="button" class="icon-btn" data-action="ext-show-password" aria-label="Show or hide password">${I('shield')}</button></span></label><div class="login-meta"><label><input type="checkbox" checked>Remember this workspace</label>${U.link('Forgot password?','ext-forgot-password')}</div></div><button class="btn primary wide" type="submit">Sign in${I('arrow')}</button><p class="login-bottom">Need help? ${U.link('Contact your administrator','ext-login-help')}</p><div class="login-demo-note">${I('shield')}Demo workspace · Sample data · No credentials are sent</div></form></section></main>`;
})();
